agent-browser eval "
// Get all tables on the page and find the one with concert dates
const tables = document.querySelectorAll('table.wikitable');
let result = '';
for (let t of tables) {
  const headers = t.querySelectorAll('th');
  const headerText = Array.from(headers).map(h => h.textContent.trim()).join(' | ');
  if (headerText.includes('Date') || headerText.includes('Venue') || headerText.includes('City')) {
    const rows = t.querySelectorAll('tr');
    for (let r of rows) {
      const cells = r.querySelectorAll('td, th');
      const rowText = Array.from(cells).map(c => c.textContent.trim().replace(/\n/g, ' ')).join(' | ');
      result += rowText + '\n';
    }
    result += '---\n';
  }
}
result || 'No matching tables found';
" 2>&1

